{
  "name": "SC10快门控制器",
  "name_en": "SC10 Shutter Controller",
  "manufacturer": "Thorlabs",
  "description": "用于控制 Thorlabs SH05 和 SH1 机械快门的控制器。可管理快门启用状态、通信波特率、工作模式，以及开/关时间、重复次数和触发相关设置，适用于光学实验中的光束通断控制与同步。",
  "description_en": "A controller for Thorlabs SH05 and SH1 mechanical shutters. It manages shutter enable state, communication baud rate, operating mode, and timing, repeat, and trigger-related settings for beam blocking/unblocking and synchronization in optical experiments.",
  "actions": [
    {
      "action_name": "auto-baud_rate",
      "description": "获取/设置通信波特率。",
      "description_en": "Get/set the communication baud rate."
    },
    {
      "action_name": "auto-default",
      "description": "恢复出厂设置。",
      "description_en": "Restore factory settings."
    },
    {
      "action_name": "auto-enable",
      "description": "获取/设置快门启用状态。",
      "description_en": "Get/set the shutter enable state."
    },
    {
      "action_name": "auto-mode",
      "description": "获取/设置工作模式。",
      "description_en": "Get/set the operating mode."
    },
    {
      "action_name": "auto-open_time",
      "description": "获取/设置快门打开时间。",
      "description_en": "Get/set the shutter open time."
    },
    {
      "action_name": "auto-out_trigger",
      "description": "获取/设置输出触发模式。",
      "description_en": "Get/set the output trigger mode."
    },
    {
      "action_name": "auto-repeat",
      "description": "获取/设置重复次数。",
      "description_en": "Get/set the repeat count."
    },
    {
      "action_name": "auto-restore",
      "description": "从存储器恢复设置。",
      "description_en": "Restore settings from memory."
    },
    {
      "action_name": "auto-save",
      "description": "将参数保存到存储器。",
      "description_en": "Save parameters to memory."
    },
    {
      "action_name": "auto-save_mode",
      "description": "将输出触发模式和波特率设置保存到存储器。",
      "description_en": "Save the output trigger mode and baud rate settings to memory."
    },
    {
      "action_name": "auto-shut_time",
      "description": "获取/设置快门关闭时间。",
      "description_en": "Get/set the shutter closed time."
    },
    {
      "action_name": "auto-trigger",
      "description": "触发快门控制动作。",
      "description_en": "Trigger the shutter control action."
    },
    {
      "action_name": "auto-name",
      "description": "获取设备名称和版本号。",
      "description_en": "Get the device name and version."
    }
  ],
  "tag_hints": [
    "optical shutter control",
    "mechanical shutter",
    "beam blocking",
    "trigger synchronization",
    "timing control",
    "serial communication",
    "Thorlabs SC10"
  ]
}

